package com.personal.assistant.module.lifemanagement.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.lifemanagement.dto.LifeManagementRequests.*;import com.personal.assistant.module.lifemanagement.service.LifeManagementService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/life-management")public class LifeManagementController{private final LifeManagementService service;public LifeManagementController(LifeManagementService service){this.service=service;}private Long uid(){return SecurityContextHelper.currentUserId();}@GetMapping("/habits")public ApiResponse<List<Map<String,Object>>>habits(){return ApiResponse.success(service.habits(uid()));}@PostMapping("/habits")public ApiResponse<Long>habit(@Valid @RequestBody Habit r){return ApiResponse.success(service.saveHabit(uid(),r));}@PostMapping("/habits/{id}/checkins")public ApiResponse<Long>checkin(@PathVariable Long id,@Valid @RequestBody Checkin r){return ApiResponse.success(service.checkin(uid(),id,r));}@GetMapping("/health/trends")public ApiResponse<Map<String,Object>>trend(@RequestParam String metricType){return ApiResponse.success(service.healthTrend(uid(),metricType));}@GetMapping("/contacts")public ApiResponse<List<Map<String,Object>>>contacts(){return ApiResponse.success(service.contacts(uid()));}@PostMapping("/contacts")public ApiResponse<Long>contact(@Valid @RequestBody Contact r){return ApiResponse.success(service.saveContact(uid(),r));}@PostMapping("/contacts/{id}/contacted")public ApiResponse<Void>contacted(@PathVariable Long id){service.markContacted(uid(),id);return ApiResponse.success();}@GetMapping("/assets")public ApiResponse<List<Map<String,Object>>>assets(){return ApiResponse.success(service.assets(uid()));}@PostMapping("/assets")public ApiResponse<Long>asset(@Valid @RequestBody Asset r){return ApiResponse.success(service.saveAsset(uid(),r));}@PostMapping("/assets/{id}/reveal")public ApiResponse<String>reveal(@PathVariable Long id,@RequestParam String verification){return ApiResponse.success(service.revealAsset(uid(),id,verification));}}
